import { expect, test, uniqueName } from "../../fixtures";

test.describe("Manage vendors", () => {
  test(
    "a vendor under review cannot be edited",
    { tag: "@VEN-09" },
    async ({ apiAs }) => {
      // Background: signed in as member@northwind.test
      const member = await apiAs("member");

      // Given a vendor in status "in_review"
      const createResponse = await member.post("/api/vendors", {
        data: {
          name: uniqueName("Acme Freight"),
          category: "logistics",
          contact_email: "ops@acmefreight.example",
        },
      });
      expect(createResponse.status(), "create vendor").toBe(201);
      const vendor = await createResponse.json();
      expect(vendor.status).toBe("draft");

      const submitResponse = await member.post(`/api/vendors/${vendor.id}/submit`);
      expect(submitResponse.status(), "submit vendor for review").toBe(200);
      const submitted = await submitResponse.json();
      expect(submitted.status).toBe("in_review");

      // When I change its contact email to "billing@acmefreight.example"
      const patchResponse = await member.patch(`/api/vendors/${vendor.id}`, {
        data: { contact_email: "billing@acmefreight.example" },
      });

      // Then the response status is 409
      expect(patchResponse.status()).toBe(409);
      // And the error code is "vendor_locked"
      const body = await patchResponse.json();
      expect(body.error.code).toBe("vendor_locked");

      // The vendor's contact email is unchanged
      const getResponse = await member.get(`/api/vendors/${vendor.id}`);
      expect(getResponse.status()).toBe(200);
      const after = await getResponse.json();
      expect(after.contact_email).toBe("ops@acmefreight.example");
      expect(after.status).toBe("in_review");
    },
  );
});
